def hasNearbyAlmostEqual(nums, indexDiff, valueDiff):
    w = valueDiff + 1
    window = {}
    for i, x in enumerate(nums):
        b = x // w
        if b in window:
            return True
        if b - 1 in window and x - window[b - 1] <= valueDiff:
            return True
        if b + 1 in window and window[b + 1] - x <= valueDiff:
            return True
        window[b] = x
        if i >= indexDiff:
            del window[nums[i - indexDiff] // w]
    return False
